'security': '#f59e0b', // Amber
'default': '#6366f1' // Indigo
};
return colors[category] || colors['default'];
}
async function generateAllBlogPosts() {
/**
* Generate OG images for all blog posts.
* Call this after publishing new posts.
*/
const blogPosts = [
{
